-- Add the prepared Zurich test area without changing write permissions.
begin;
-- Optional presentation fields; existing documents remain valid. Apply before new clients.
create or replace function ast_private.project_schema() returns jsonb language sql immutable set search_path = '' as $schema$
select '{"type":"object","properties":{"id":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"schemaVersion":{"type":"number","enum":[1,2]},"name":{"type":"string","max":120,"nonempty":true},"mapPackageId":{"type":"string","enum":["benglen","mahlwinkel","zurich"]},"teams":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"name":{"type":"string","max":120,"nonempty":true},"shortLabel":{"type":"string","max":12,"nonempty":true},"colour":{"type":"string","max":7,"nonempty":false,"pattern":"^#[0-9a-fA-F]{6}$"}},"required":["id","name","shortLabel","colour"]},"min":0,"max":100},"phases":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"order":{"type":"number","min":0,"max":9007199254740991,"integer":true},"title":{"type":"string","max":120,"nonempty":true},"notes":{"type":"string","max":10000,"nonempty":false},"camera":{"anyOf":[{"type":"null"},{"type":"object","properties":{"center":{"type":"array","items":{"type":"number","min":-180,"max":180,"integer":false},"min":2,"max":2},"zoom":{"type":"number","min":0,"max":24,"integer":false},"bearing":{"type":"number","min":-360,"max":360,"integer":false},"pitch":{"type":"number","min":0,"max":85,"integer":false}},"required":["center","zoom","bearing","pitch"]}]},"visibleElementIds":{"type":"array","items":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"min":0,"max":500,"unique":true}},"required":["id","order","title","notes","camera","visibleElementIds"]},"min":0,"max":100},"elements":{"type":"array","items":{"type":"object","properties":{"id":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"projectId":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"type":{"type":"string","enum":["point","text","line","freehand","polygon","circle"]},"geometry":{"anyOf":[{"type":"object","properties":{"type":{"type":"string","enum":["Point"]},"coordinates":{"type":"array","items":{"type":"number","min":-180,"max":180,"integer":false},"min":2,"max":2}},"required":["type","coordinates"]},{"type":"object","properties":{"type":{"type":"string","enum":["LineString"]},"coordinates":{"type":"array","items":{"type":"array","items":{"type":"number","min":-180,"max":180,"integer":false},"min":2,"max":2},"min":2,"max":5000}},"required":["type","coordinates"]},{"type":"object","properties":{"type":{"type":"string","enum":["Polygon"]},"coordinates":{"type":"array","items":{"type":"array","items":{"type":"array","items":{"type":"number","min":-180,"max":180,"integer":false},"min":2,"max":2},"min":4,"max":5000},"min":1,"max":100}},"required":["type","coordinates"]},{"type":"object","properties":{"type":{"type":"string","enum":["Circle"]},"center":{"type":"array","items":{"type":"number","min":-180,"max":180,"integer":false},"min":2,"max":2},"radiusMeters":{"type":"number","min":0.1,"max":100000,"integer":false}},"required":["type","center","radiusMeters"]}]},"label":{"type":"string","max":200,"nonempty":false},"notes":{"type":"string","max":10000,"nonempty":false},"teamId":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"phaseIds":{"type":"array","items":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"min":0,"max":500,"unique":true},"style":{"type":"object","properties":{"colour":{"type":"string","max":7,"nonempty":false,"pattern":"^#[0-9a-fA-F]{6}$"},"width":{"type":"number","min":1,"max":20,"integer":false},"opacity":{"type":"number","min":0,"max":1,"integer":false},"symbol":{"type":"string","enum":["auto","none","pin","flag","shield","warning","building","aid"]},"pattern":{"type":"string","enum":["auto","solid","hatch","cross","dots","outline"]},"labelMode":{"type":"string","enum":["auto","always","hidden"]}},"required":["colour","width","opacity"]},"version":{"type":"number","min":1,"max":9007199254740991,"integer":true},"deletedAt":{"type":"string","max":24,"nonempty":false,"pattern":"^\\d{4}-\\d\\d-\\d\\dT\\d\\d:\\d\\d:\\d\\d\\.\\d{3}Z$"},"layerId":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"sourceId":{"type":"string","max":200,"nonempty":true}},"required":["id","projectId","type","geometry","label","notes","phaseIds","style","version"]},"min":0,"max":500},"workspace":{"type":"object","required":["layers","siteId","eventId","edition","source"],"properties":{"layers":{"type":"array","max":32,"items":{"type":"object","required":["id","name","opacity","locked"],"properties":{"id":{"type":"string","max":36,"nonempty":false,"pattern":"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-8][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$"},"name":{"type":"string","max":80,"nonempty":true},"opacity":{"type":"number","min":0,"max":1},"locked":{"type":"boolean"}}}},"siteId":{"type":"string","max":120},"eventId":{"type":"string","max":120},"edition":{"type":"string","max":120},"source":{"type":"string","max":2000}}}},"required":["id","schemaVersion","name","mapPackageId","teams","phases","elements"]}'::jsonb;
$schema$;

create or replace function public.ast_publish(p_id uuid, p_document jsonb, p_map jsonb) returns uuid
language plpgsql security definer set search_path = '' as $$
declare w jsonb;
begin
    -- Row lock serializes publication with root revocation.
    perform 1 from ast_private.roots where user_id=auth.uid() for share;
    if not found then raise exception 'forbidden' using errcode = '42501'; end if;
    if p_id is null or p_document is null or p_map is null then raise exception 'invalid_package' using errcode = '22023'; end if;
    -- The collaborative map whitelist is not applicable to immutable bundled local areas.
    perform ast_private.validate_project(jsonb_set(p_document,'{mapPackageId}','"mahlwinkel"'::jsonb));
    w := p_document->'workspace';
    if w is null or btrim(w->>'siteId')='' or btrim(w->>'eventId')='' or btrim(w->>'edition')='' or btrim(w->>'source')=''
        or p_document->>'mapPackageId' is distinct from p_map->>'id'
        or coalesce(p_map->>'id','') !~ '^(mahlwinkel|benglen|zurich|local-[0-9a-f-]{36})$'
        or p_map->>'format' is distinct from 'as-tac-map' or p_map->>'formatVersion' is distinct from '1'
        or p_map->>'license' is distinct from 'ODbL 1.0' or p_map->>'attribution' is distinct from '© OpenStreetMap contributors'
        or jsonb_typeof(p_map->'data') is distinct from 'object' or octet_length(p_map::text)>30000000
        or coalesce(p_map->>'sha256','') !~ '^[0-9a-f]{64}$' then
        raise exception 'invalid_package' using errcode = '22023';
    end if;
    -- No update path: even root publishes a new edition rather than changing a downloaded one.
    insert into ast_private.catalog values(p_id,w->>'siteId',w->>'eventId',w->>'edition',p_document->>'name',p_document,p_map,auth.uid(),now());
    return p_id;
end;
$$;

commit;
